import { expect, test } from "@playwright/test";

/**
 * The full journey on the bundled sample: open the app, run a real analysis,
 * explore the graph, inspect relationships, search, trace a flow and check impact.
 */
test("explore the sample project end to end", async ({ page }) => {
  await page.goto("/");
  await expect(page.getByRole("heading", { name: "Understand the code beneath the interface." })).toBeVisible();
  // The hero cross-section is generated by the analyzer at build time.
  await expect(page.getByText("PUT /api/documents/[id]").first()).toBeVisible();

  await page.getByRole("link", { name: "Explore the demo" }).click();

  // Analysis runs, then the architecture map opens.
  await expect(page).toHaveURL(/\/workspace\/[\w-]+\/map/, { timeout: 30_000 });
  const saveButtonNode = page.locator(".react-flow__node").filter({ hasText: "SaveButton" });
  await expect(saveButtonNode).toBeVisible();

  // Select a node: the inspector shows its real relationships.
  await saveButtonNode.click();
  const inspector = page.getByRole("complementary", { name: "Inspector: SaveButton" });
  await expect(inspector).toBeVisible();
  await expect(inspector.getByText("src/components/editor/SaveButton.tsx:8–14")).toBeVisible();
  await expect(inspector.getByRole("button", { name: /DocumentEditor/ })).toBeVisible();
  await expect(inspector.getByText("onSave", { exact: true })).toBeVisible();

  // Source tab shows the analyzed file.
  await inspector.getByRole("tab", { name: "Source" }).click();
  await expect(inspector.getByText("export function SaveButton")).toBeVisible();

  // Command palette search navigates to a hook.
  await page.keyboard.press("Control+k");
  const palette = page.getByRole("dialog", { name: "Search the architecture" });
  await palette.getByRole("combobox").fill("useSaveDoc");
  await expect(palette.getByRole("option").first()).toContainText("useSaveDocument");
  await page.keyboard.press("Enter");
  await expect(page.getByRole("complementary", { name: "Inspector: useSaveDocument" })).toBeVisible();

  // Data flow from the Save button reaches the database.
  await page.getByRole("link", { name: "Data flows" }).click();
  await page.getByRole("complementary", { name: "Entry points" }).getByRole("button", { name: /onClick "Save"/ }).click();
  const strata = page.getByRole("list", { name: "Flow, layer by layer" });
  await expect(strata.getByText("documentsApi.save", { exact: true })).toBeVisible();
  await expect(strata.getByText("PUT /api/documents/[id]", { exact: true })).toBeVisible();
  await expect(strata.getByText("document.update", { exact: true })).toBeVisible();

  // Impact analysis of the document service.
  await page.getByRole("link", { name: "Impact analysis" }).click();
  await page.getByLabel("Choose an element").fill("DocumentService");
  await page.keyboard.press("Enter");
  await expect(page.getByRole("heading", { name: "What might break if DocumentService changes" })).toBeVisible();
  await expect(page.getByRole("list", { name: "Dependents by distance" }).getByText("archiveDocument")).toBeVisible();
});

test("API exports are generated from the stored analysis", async ({ request }) => {
  const demo = await request.post("/api/demo", { headers: { Origin: "http://127.0.0.1:4311" } });
  expect(demo.ok()).toBeTruthy();
  const { analysis } = await demo.json();
  for (let i = 0; i < 60; i++) {
    const status = await (await request.get(`/api/analyses/${analysis.id}`)).json();
    if (status.analysis.status === "completed") break;
    await new Promise((r) => setTimeout(r, 250));
  }
  const md = await request.get(`/api/analyses/${analysis.id}/export?format=markdown`);
  expect(md.headers()["content-disposition"]).toContain("architecture.md");
  expect(await md.text()).toContain("## API inventory");

  const source = await request.get(`/api/analyses/${analysis.id}/source?file=${encodeURIComponent("../package.json")}`);
  expect(source.status()).toBe(404);
});

test("rejects cross-site writes", async ({ request }) => {
  const res = await request.post("/api/projects", { data: { source: "sample" }, headers: { Origin: "https://evil.example" } });
  expect(res.status()).toBe(403);
});
